effect.shader:
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmFirefly(vec2 uv, float cols, float seed, float t, float range, float sizePx, float tight, float aspect, float gate){
vec2 p = uv * vec2(cols, cols / max(aspect * 1.2, 0.6));
vec2 cell = floor(p);
float h = gmHash2(cell + seed);
if (h < gate) return 0.0;
vec2 f = fract(p) - 0.5;
float h2 = gmHash2(cell * 3.7 + seed * 5.1);
float h3 = gmHash2(cell * 9.1 + seed * 11.3);
vec2 home = vec2(h2 - 0.5, h3 - 0.5) * 0.5;
float wa = t * (0.25 + h2 * 0.5) + h * 6.2831;
float wb = t * (0.13 + h3 * 0.35) + h2 * 6.2831;
vec2 pos = home + vec2(sin(wa), cos(wb)) * 0.34 * range;
float d = length(f - pos);
float core = exp(-d * d / (sizePx * sizePx * tight * tight));
float halo = exp(-d * d / (sizePx * sizePx * 3.2));
return (core * 1.2 + halo * 0.5);
}
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
float gate = 1.0 - flyAmount * 0.01;
float flick = 1.0 - flicker * 0.5 + flicker * 0.5 * sin(acTime * (2.0 + flySize) + uv.x * 90.0 + uv.y * 130.0);
float f1 = gmFirefly(uv, 7.0, 3.0, acTime * wanderSpeed, wanderRange, flySize, coreTight, aspect, gate);
float f2 = gmFirefly(uv, 11.0, 17.0, acTime * wanderSpeed * 1.3, wanderRange * 0.8, flySize * 0.75, coreTight, aspect, gate);
float f3 = gmFirefly(uv, 16.0, 41.0, acTime * wanderSpeed * 0.8, wanderRange * 1.2, flySize * 0.55, coreTight, aspect, gate);
float flies = (f1 + f2 * 0.8 + f3 * 0.6) * flyBright * max(flick, 1.0 - flicker);
vec3 col = src.rgb * src.a + flyColor.rgb * min(flies, 2.5) * src.a;
gl_FragColor = vec4(col, src.a);
}
